<template><div class="app-container"><div class="page-header"><div><h1>{{ walletOnly?'Credits Wallets':'User Rights' }}</h1><p>{{ walletOnly?'Per-user balance and independently expiring batches.':'Effective Base + Additional rights, purchased versions and saved assets.' }}</p></div><div class="page-actions"><el-button icon="el-icon-refresh" @click="load">Refresh</el-button><interaction-notes :title="walletOnly?'Credits Wallets':'User Rights'" :notes="notes"/></div></div><el-form inline class="filter-container"><el-form-item><el-input v-model="search" clearable placeholder="User name or ID" class="search-input"/></el-form-item></el-form><el-table v-loading="loading" :data="filtered" row-key="id" border><el-table-column label="User" min-width="210"><template slot-scope="s"><div class="item-name">{{ s.row.name }}</div><div class="item-code">{{ s.row.id }}</div></template></el-table-column><el-table-column label="Effective Base" min-width="160"><template slot-scope="s">{{ s.row.effective.base.name }} · v{{ s.row.effective.base.version }}</template></el-table-column><el-table-column label="Additional" width="100"><template slot-scope="s">{{ s.row.effective.additional.length }}</template></el-table-column><el-table-column prop="wallet.available" label="Available" width="105"/><el-table-column prop="wallet.reserved" label="Reserved" width="100"/><el-table-column label="Action" width="140"><template slot-scope="s"><el-button type="text" @click="$router.push({path:'/commercialization/users/'+s.row.id,query:walletOnly?{tab:'wallet'}:{}})">{{ walletOnly?'View Batches':'View Rights' }}</el-button></template></el-table-column></el-table></div></template>
<script>
import {listUsers} from '@/api/commerce'
import InteractionNotes from '@/components/InteractionNotes'
export default{components:{InteractionNotes},props:{walletOnly:Boolean},data(){return{rows:[],search:'',loading:false,notes:[{title:'有效权益',rule:'同一时刻一个有效 Base，叠加所有有效 Additional；范围合并，ALL 覆盖局部范围。',interaction:'显示来源、授权版本和期限，不直接编辑合并结果。'},{title:'独立额度',rule:'赠送、购买和补偿额度分批记录，按先到期顺序使用。可用额度不包含已预留或已过期额度。',interaction:'从用户详情查看批次、预留和消费分配；补偿新建批次并填写原因。'},{title:'到期保留',rule:'会员到期后回落到 Free；已有报告、计划、聊天和有效独立兑换仍保留。',interaction:'读取旧资产免费；发起新操作重新检查功能权益及 Credits。'}]}},computed:{filtered(){return this.rows.filter(r=>(r.name+' '+r.id).toLowerCase().includes(this.search.toLowerCase()))}},created(){this.load()},methods:{async load(){this.loading=true;try{this.rows=await listUsers()}finally{this.loading=false}}}}
</script>
